import{_ as a,o as t,c as r,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Orchestrator Meeting 2020-08-03","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2020-08-03","date":"2020-08-03T00:00:00.000Z","updated":"2020-08-04T00:00:00.000Z","tags":["Ceph","Orchestrator","Distributed Storage","CephFS","Rook"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-08-03.md","filePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-08-03.md","lastUpdated":1780459816000}'),i={name:"posts/2020/Ceph_Orchestrator_Meeting_2020-08-03.md"};function o(h,e,s,n,c,p){return t(),r("div",null,[...e[0]||(e[0]=[l('<h3 id="会议纪要-ceph-orchestrator-周会" tabindex="-1">会议纪要：Ceph Orchestrator 周会 <a class="header-anchor" href="#会议纪要-ceph-orchestrator-周会" aria-label="Permalink to &quot;会议纪要：Ceph Orchestrator 周会&quot;">​</a></h3><h4 id="会议时间-2020年8月3日" tabindex="-1">会议时间：2020年8月3日 <a class="header-anchor" href="#会议时间-2020年8月3日" aria-label="Permalink to &quot;会议时间：2020年8月3日&quot;">​</a></h4><h4 id="参会人员-参会人员名单" tabindex="-1">参会人员：[参会人员名单] <a class="header-anchor" href="#参会人员-参会人员名单" aria-label="Permalink to &quot;参会人员：[参会人员名单]&quot;">​</a></h4><h4 id="会议议程" tabindex="-1">会议议程： <a class="header-anchor" href="#会议议程" aria-label="Permalink to &quot;会议议程：&quot;">​</a></h4><ol><li>显示警告消息</li><li>OSD 移除设计命令</li><li>改进 Ceph Orchestrator 的开发者体验</li><li>使用单一容器镜像</li></ol><h4 id="讨论内容" tabindex="-1">讨论内容： <a class="header-anchor" href="#讨论内容" aria-label="Permalink to &quot;讨论内容：&quot;">​</a></h4><ol><li><p><strong>显示警告消息</strong></p><ul><li>讨论了通过 Ceph 健康检查向用户传播警告消息的方法。</li><li>讨论了改进警告消息的显示方式，使其在仪表盘或健康输出中可见。</li><li>讨论了自动解决警告消息的机制，当前每六分钟自动解决一次。</li><li>提出了是否应允许用户手动触发健康检查循环的讨论。</li></ul></li><li><p><strong>OSD 移除设计命令</strong></p><ul><li>讨论了 Rook 和 Ceph 在 OSD 移除方面的设计。</li><li>讨论了 Rook 不自动移除 OSD，而是提供一个一次性操作的 Kubernetes 作业。</li><li>讨论了与 Ceph 的相似性和差异，包括安全措施和强制标志。</li></ul></li><li><p><strong>改进 Ceph Orchestrator 的开发者体验</strong></p><ul><li>讨论了如何改进 Ceph Orchestrator 的开发者体验。</li><li>提出了将 Ceph Orchestrator 变为一个适当的 Python 包的建议。</li></ul></li><li><p><strong>使用单一容器镜像</strong></p><ul><li>讨论了在集群中使用单一容器镜像的需求。</li><li>提出了在 Ceph Orchestrator 中使用单一容器镜像的建议。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>实现自动解决警告消息的机制。</li><li>更新设计文档以反映新的 OSD 移除方法。</li><li>进行基础工作，将 Ceph Orchestrator 变为一个适当的 Python 包。</li><li>实现将标签转换为摘要的方法，确保集群中使用单一容器镜像的一致性。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议结束，下次会议定于下周同一时间进行。</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li>会议中提到的具体拉取请求和设计文档链接已记录在会议笔记中，供后续参考。</li></ul>',13)])])}const _=a(i,[["render",o]]);export{u as __pageData,_ as default};
